# Search for each song in songs_to_archive to get their song IDs
song_id_map = {}  # (title, artist) -> song_id
for song in songs_to_archive:
    title = song["title"]
    artist = song["artist"]
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=login_result["access_token"], page_limit=20)
    found = None
    for r in results:
        # Check if any artist matches
        for a in r["artists"]:
            if a["name"].lower() == artist.lower():
                found = r
                break
        if found:
            break
    if found:
        song_id_map[(title, artist)] = found["song_id"]
        print(f"Found: {title} by {artist} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title} by {artist}")

print(f"\nTotal found: {len(song_id_map)} out of {len(songs_to_archive)}")

