steps.code:
# Let's search for each song in the list and collect their song_ids
# We already have the first search result for "City of Fallen Angels"
# Let's search for the remaining songs

# First, let's define a helper to match a song result to our target
def match_song(result, target):
    if result['title'].lower() != target['title'].lower():
        return False
    result_artists = {a['name'].lower() for a in result['artists']}
    target_artists = {a.lower() for a in target['artists']}
    return result_artists == target_artists

# We'll collect song_ids in a dict mapping song title to song_id
archived_song_ids = {}

# First song already searched
first_target = songs_to_archive[0]
for r in search_result:
    if match_song(r, first_target):
        archived_song_ids[first_target['title']] = r['song_id']
        break

# Search remaining songs
for song in songs_to_archive[1:]:
    # Search by title
    results = apis.spotify.search_songs(query=song['title'], access_token=spotify_login['access_token'])
    found = False
    for r in results:
        if match_song(r, song):
            archived_song_ids[song['title']] = r['song_id']
            found = True
            break
    if not found:
        print(f"Could not find song: {song['title']} by {song['artists']}")

print("Archived song IDs found:")
print(archived_song_ids)

