steps.code:
# Parse the note content to extract missing songs
content = note['content']
lines = content.split('\n')
missing_songs = []
for line in lines:
    if line.startswith('- '):
        # Format: - Song Title BY Artist(s) RELEASED_AT TODO or RELEASED_AT MM/YYYY
        # Remove leading "- "
        entry = line[2:]
        # Split on " RELEASED_AT "
        if ' RELEASED_AT ' in entry:
            song_part, release_part = entry.split(' RELEASED_AT ', 1)
            if release_part == 'TODO':
                # Extract title and artists
                # Format: "Song Title BY Artist1, Artist2"
                if ' BY ' in song_part:
                    title, artists = song_part.split(' BY ', 1)
                    missing_songs.append({'title': title, 'artists': artists, 'line': line})
                else:
                    print("Unexpected format:", entry)
            else:
                # Already has release date, skip
                pass
        else:
            print("No RELEASED_AT found:", entry)
print("Missing songs count:", len(missing_songs))
for s in missing_songs:
    print(s['title'], "by", s['artists'])

