steps.code:
# Parse the note content to extract songs with TODO
lines = note_content.split('\n')
songs_todo = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        entry = line[2:]
        # Split on " BY " to get title and artist part
        if ' BY ' in entry:
            title_part, artist_part = entry.split(' BY ', 1)
            # artist_part may contain " RELEASED_AT TODO" or " RELEASED_AT MM/YYYY"
            if ' RELEASED_AT ' in artist_part:
                artist_str, released = artist_part.split(' RELEASED_AT ', 1)
                if released == 'TODO':
                    songs_todo.append((title_part.strip(), artist_str.strip()))
print("Songs with TODO:")
for title, artists in songs_todo:
    print(f"{title} by {artists}")

